let rhythmMode=localStorage.getItem('groovelab_rhythm_mode')==='lock'?'lock':'auto',danceBpm=clamp(Number(localStorage.getItem('groovelab_dance_bpm')||110),50,210),moveHold=clamp(Number(localStorage.getItem('groovelab_move_hold')||4),4,16),onsetSensitivity=clamp(Number(localStorage.getItem('groovelab_onset_sensitivity')||55),20,90);
