 document.addEventListener('keydown',e=>{if(e.key==='Escape'&&!overlay.hidden){close();e.preventDefault();}if(e.key==='ArrowRight'&&!overlay.hidden){next(1);}});
 overlay.addEventListener('dblclick',e=>{if(e.target.tagName==='CANVAS')close();});
