$('randomDance').checked=danceRandom;$('beatSyncDance').checked=danceSync;$('danceEnergy').value=Math.round(danceIntensity*100);$('rhythmMode').value=rhythmMode;$('danceBpm').value=danceBpm;$('moveHold').value=moveHold;$('onsetSensitivity').value=onsetSensitivity;
$('randomDance').onchange=e=>{danceRandom=e.target.checked;localStorage.setItem('groovelab_random_dance',danceRandom);if(!danceRandom)$$('.avatar-float').forEach(d=>{d.dataset.move=d.dataset.defaultMove;d.dataset.prevMove=d.dataset.defaultMove;});};
$('beatSyncDance').onchange=e=>{danceSync=e.target.checked;localStorage.setItem('groovelab_beat_sync',danceSync);if(danceSync)lastBeatAt=performance.now();};
$('danceEnergy').oninput=e=>{danceIntensity=Number(e.target.value)/100;localStorage.setItem('groovelab_dance_intensity',e.target.value);};
$('rhythmMode').onchange=e=>{rhythmMode=e.target.value;localStorage.setItem('groovelab_rhythm_mode',rhythmMode);lastBeatAt=performance.now();if(rhythmDetector)rhythmDetector.reset();updateRhythmDashboard(true);};
$('danceBpm').onchange=e=>{danceBpm=clamp(Number(e.target.value)||110,50,210);e.target.value=danceBpm;localStorage.setItem('groovelab_dance_bpm',danceBpm);if(rhythmMode==='lock')lastBeatAt=performance.now();updateRhythmDashboard(true);};
$('moveHold').onchange=e=>{moveHold=clamp(Number(e.target.value)||8,4,16);localStorage.setItem('groovelab_move_hold',moveHold);};
