   if(armR)armR.style.transform=`translate(${(pose.torso*.16).toFixed(1)}px,${(-Math.max(0,pose.elbowR)*.08).toFixed(1)}px) rotate(${pose.armR.toFixed(1)}deg)`;
   if(legL)legL.style.transform=`translate(${(pose.hip*.08).toFixed(1)}px,${(-pose.kneeL*.05).toFixed(1)}px) rotate(${pose.legL.toFixed(1)}deg)`;
   if(legR)legR.style.transform=`translate(${(pose.hip*.08).toFixed(1)}px,${(-pose.kneeR*.05).toFixed(1)}px) rotate(${pose.legR.toFixed(1)}deg)`;
   if(head)head.style.transform=`translate(${(-pose.torso*.08).toFixed(1)}px,${(-pose.head*.1).toFixed(1)}px) rotate(${pose.head.toFixed(1)}deg)`;
   const wings=sprite.querySelector('.sprite-wings');if(wings)wings.style.transform=`scaleX(${(1+Math.sin(clock*2*Math.PI)*.08*intensity).toFixed(3)}) rotate(${(-Math.sin(clock*Math.PI)*4*intensity).toFixed(1)}deg)`;const foreL=sprite.querySelector('.sprite-forearm-left'),foreR=sprite.querySelector('.sprite-forearm-right'),shinL=sprite.querySelector('.sprite-shin-left'),shinR=sprite.querySelector('.sprite-shin-right'),torso=sprite.querySelector('.sprite-torso'),hair=sprite.querySelector('.sprite-hair-back');
   if(foreL)foreL.style.transform=`rotate(${pose.elbowL.toFixed(1)}deg)`;
   if(foreR)foreR.style.transform=`rotate(${pose.elbowR.toFixed(1)}deg)`;
